6	export interface Walker { x: number; z: number; lo: number; hi: number; dir: number; speed: number; profile: (c: number) => number; axis?: 'x' | 'z' }
7	export interface People { list: Walker[]; mesh: THREE.InstancedMesh; group: THREE.Group }
8	
9	export function createPeople(bridge: { group: THREE.Group; noReflect: THREE.Object3D[] }, list: Walker[], mat: THREE.Material, name: string, rnd: () => number): People {
10	  const body = mergeGeometries([new THREE.CylinderGeometry(0.19, 0.24, 1.25, 7).translate(0, 0.63, 0), new THREE.SphereGeometry(0.13, 8, 6).translate(0, 1.42, 0)]);
11	  const mesh = new THREE.InstancedMesh(body, mat, list.length), col = new THREE.Color();
12	  const clothes = [0xd94b3d, 0x2f6fb5, 0xf2f2ee, 0x3a3a3a, 0xe0b23a, 0x4f9a5a, 0xc76fa8];
13	  list.forEach((_p, i) => mesh.setColorAt(i, col.setHex(clothes[Math.floor(rnd() * clothes.length)])));
14	  mesh.frustumCulled = false; mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
15	  const group = new THREE.Group(); group.name = name; group.add(mesh);
16	  bridge.group.add(group); bridge.noReflect.push(group);
17	  return { list, mesh, group };
18	}
19	const _pm = new THREE.Matrix4(), _pq = new THREE.Quaternion(), _pv = new THREE.Vector3(), _one = new THREE.Vector3(1, 1, 1);   // vector tạm cấp sẵn (D-018)
20	export function stepPeople(P: People, dt: number, elapsed: number) {
21	  const m = _pm, q = _pq, v = _pv, one = _one;
22	  P.list.forEach((p, i) => {
23	    const alongZ = p.axis === 'z', key = alongZ ? 'z' : 'x';
24	    p[key] += p.dir * p.speed * dt; if (p[key] > p.hi) p[key] = p.lo; if (p[key] < p.lo) p[key] = p.hi;
25	    const y = p.profile(p[key]) + 0.05 * Math.abs(Math.sin(elapsed * 5.5 + i));
26	    q.setFromAxisAngle(UP, alongZ ? (p.dir > 0 ? -Math.PI / 2 : Math.PI / 2) : (p.dir > 0 ? 0 : Math.PI));
27	    P.mesh.setMatrixAt(i, m.compose(v.set(p.x, y, p.z), q, one));
28	  });
29	  P.mesh.instanceMatrix.needsUpdate = true;
30	}
